/// <summary>
/// Import tests for animated and rigged assets: generic root motion, humanoid avatars and how both interact with
/// "Remove Empty Root Objects". The test assets are generated by Tests/Assets/Rigs/Generator~/generate-rig-test-assets.js.
/// Each asset is copied into a temporary folder in Assets, so changing import settings never touches the package's .meta files.
/// Roundtrip tests (import, export, import) are in RigImportTests.Roundtrip.cs.
/// </summary>
public partial class RigImportTests
{
	private const string SourceFolder = "Packages/org.khronos.unitygltf/Tests/Assets/Rigs";
	private const string TempFolder = "Assets/UnityGLTFTests_Rigs";

	private const string RootMotionEmptyRoot = "RootMotion_EmptyRoot.glb";
	private const string RootMotionAnimatedRoot = "RootMotion_AnimatedRoot.glb";
	private const string StaticNoAnimation = "Static_NoAnimation.glb";
	private const string HumanoidArmature = "Humanoid_Armature.glb";
	private const string HumanoidMixamo = "Humanoid_Mixamo.glb";
	private const string HumanoidAPose = "Humanoid_APose.glb";
	private const string HumanoidUnrealNames = "Humanoid_UnrealNames.glb";
	// Humanoid_Armature with a "Prop" below RightHand: Walk also spins it, PropOnly only moves the prop
	private const string HumanoidProps = "Humanoid_Props.glb";

	[OneTimeSetUp]
	public void OneTimeSetUp()
	{
		if (!AssetDatabase.IsValidFolder(TempFolder))
			AssetDatabase.CreateFolder("Assets", Path.GetFileName(TempFolder));
	}

	[OneTimeTearDown]
	public void OneTimeTearDown()
	{
		AssetDatabase.DeleteAsset(TempFolder);
	}

	#region Helpers

	private static void CopyTestAsset(string file, string path)
	{
		var source = FileUtil.GetPhysicalPath($"{SourceFolder}/{file}");
		Assert.IsTrue(File.Exists(source), $"Test asset not found: {source}");
		File.Copy(source, path, true);
		AssetDatabase.ImportAsset(path, ImportAssetOptions.ForceSynchronousImport);
	}

	private static string Import(string file, AnimationMethod method, string rootNodeName = "", bool removeEmptyRoots = true, bool humanoidFlip = false, bool readWrite = true)
	{
		var path = $"{TempFolder}/{file}";
		if (!File.Exists(path))
			CopyTestAsset(file, path);

		Reimport(path, method, rootNodeName, removeEmptyRoots, humanoidFlip, readWrite);
		return path;
	}

	/// <summary>
	/// Sets the import settings of an asset in the temp folder and reimports it.
	/// </summary>
	internal static void Reimport(string path, AnimationMethod method, string rootNodeName = "", bool removeEmptyRoots = true, bool humanoidFlip = false, bool readWrite = true)
	{
		var importer = AssetImporter.GetAtPath(path) as GLTFImporter;
		Assert.IsNotNull(importer, $"{path} is not imported with the {nameof(GLTFImporter)}");

		var so = new SerializedObject(importer);
		so.FindProperty("_importAnimations").intValue = (int)method;
		so.FindProperty("_nonHumanoidRootNodeName").stringValue = rootNodeName;
		so.FindProperty("_removeEmptyRootObjects").boolValue = removeEmptyRoots;
		so.FindProperty("_mecanimHumanoidFlip").boolValue = humanoidFlip;
		so.FindProperty("_readWriteEnabled").boolValue = readWrite;
		so.ApplyModifiedPropertiesWithoutUndo();
		importer.SaveAndReimport();
	}

	internal static GameObject LoadModel(string path)
	{
		var model = AssetDatabase.LoadAssetAtPath<GameObject>(path);
		Assert.IsTrue(model, $"No model imported at {path}");
		return model;
	}

	internal static Avatar LoadAvatar(string path) => AssetDatabase.LoadAllAssetsAtPath(path).OfType<Avatar>().SingleOrDefault();

	internal static AnimationClip[] LoadClips(string path) => AssetDatabase.LoadAllAssetsAtPath(path).OfType<AnimationClip>().ToArray();

	private static void AssertClipBindingsResolve(string path)
	{
		var model = LoadModel(path);
		foreach (var clip in LoadClips(path))
		foreach (var binding in AnimationUtility.GetCurveBindings(clip))
		{
			var target = string.IsNullOrEmpty(binding.path) ? model.transform : model.transform.Find(binding.path);
			Assert.IsTrue(target, $"Clip \"{clip.name}\" animates \"{binding.path}\", which doesn't exist below \"{model.name}\"");
		}
	}

