	[TestCase(HumanoidArmature, "Hips", "LeftUpperArm", "RightToes")]
	[TestCase(HumanoidMixamo, "mixamorig:Hips", "mixamorig:LeftArm", "mixamorig:RightToeBase")]
	public void Humanoid_MapsAllRequiredBones(string file, string hips, string leftUpperArm, string rightToes)
	{
		var path = Import(file, AnimationMethod.MecanimHumanoid);
		var human = LoadAvatar(path).humanDescription.human;
		var mapping = human.ToDictionary(b => b.humanName, b => b.boneName);

		for (var i = 0; i < HumanTrait.BoneCount; i++)
		{
			if (!HumanTrait.RequiredBone(i)) continue;
			Assert.IsTrue(mapping.ContainsKey(HumanTrait.BoneName[i]), $"Required bone {HumanTrait.BoneName[i]} is not mapped");
