		Assert.AreEqual(hips, mapping["Hips"]);
		Assert.AreEqual(leftUpperArm, mapping["LeftUpperArm"]);
		Assert.AreEqual(rightToes, mapping["RightToes"]);
	}

	[Test]
	public void Humanoid_UnknownBoneNames_AreMappedAutomatically()
	{
		// Unreal style names aren't in UnityGLTF's name dictionary, so Unity's auto mapping has to find them
		var path = Import(HumanoidUnrealNames, AnimationMethod.MecanimHumanoid);
		var avatar = LoadAvatar(path);
		Assert.IsNotNull(avatar, "No valid human avatar for a rig with Unreal bone names");
		var mapping = avatar.humanDescription.human.ToDictionary(b => b.humanName, b => b.boneName);

		for (var i = 0; i < HumanTrait.BoneCount; i++)
		{
			if (!HumanTrait.RequiredBone(i)) continue;
			Assert.IsTrue(mapping.ContainsKey(HumanTrait.BoneName[i]), $"Required bone {HumanTrait.BoneName[i]} is not mapped");
		}

		Assert.AreEqual("pelvis", mapping["Hips"]);
		Assert.AreEqual("upperarm_l", mapping["LeftUpperArm"]);
		Assert.AreEqual("lowerarm_r", mapping["RightLowerArm"]);
		Assert.AreEqual("thigh_l", mapping["LeftUpperLeg"]);
		Assert.AreEqual("calf_r", mapping["RightLowerLeg"]);
	}

