	/// <summary>
	/// Direction from the upper to the lower arm, in the skeleton pose stored in the avatar (or in the model's own pose).
	/// </summary>
	private static Vector3 ArmDirection(string path, string side, bool useAvatarSkeleton)
	{
		var avatar = LoadAvatar(path);
		var instance = Object.Instantiate(LoadModel(path));
		try
		{
			var transforms = instance.GetComponentsInChildren<Transform>(true).GroupBy(t => t.name).ToDictionary(g => g.Key, g => g.First());
			if (useAvatarSkeleton)
			{
				foreach (var bone in avatar.humanDescription.skeleton)
				{
					if (!transforms.TryGetValue(bone.name, out var t) || t == instance.transform) continue;
					t.localPosition = bone.position;
					t.localRotation = bone.rotation;
				}
			}

			var mapping = avatar.humanDescription.human.ToDictionary(b => b.humanName, b => b.boneName);
			var upperArm = transforms[mapping[side + "UpperArm"]];
			var lowerArm = transforms[mapping[side + "LowerArm"]];
			return (lowerArm.position - upperArm.position).normalized;
		}
		finally
		{
			Object.DestroyImmediate(instance);
		}
	}

	[TestCase("Left")]
	[TestCase("Right")]
	public void Humanoid_APose_IsCorrectedToTPose(string side)
	{
		var path = Import(HumanoidAPose, AnimationMethod.MecanimHumanoid);

		var modelArm = ArmDirection(path, side, useAvatarSkeleton: false);
		Assert.Less(modelArm.y, -0.5f, $"Test asset should be in A-pose, but the {side} arm points {modelArm}");

		var avatarArm = ArmDirection(path, side, useAvatarSkeleton: true);
		Assert.AreEqual(0f, avatarArm.y, 0.1f, $"The avatar's skeleton pose should be a T-pose, but the {side} arm points {avatarArm}");
	}

