	#region Root motion playback

	/// <summary>
	/// Plays a clip on an instance of the imported model and returns how far the instance itself moved.
	/// </summary>
	private static (Vector3 instanceOffset, Vector3 rootNodeOffset) PlayClip(string path, string clipName, float seconds)
	{
		var (instanceOffset, rootNodeOffset, _) = PlayClipWithRotation(path, clipName, seconds);
		return (instanceOffset, rootNodeOffset);
	}

	private static (Vector3 instanceOffset, Vector3 rootNodeOffset, Quaternion instanceRotation) PlayClipWithRotation(string path, string clipName, float seconds)
	{
		var clip = LoadClips(path).Single(c => c.name == clipName);
		var instance = Object.Instantiate(LoadModel(path));
		var graph = PlayableGraph.Create("RigImportTests");
		try
		{
			var animator = instance.GetComponent<Animator>();
			Assert.IsTrue(animator);

			// Search the whole hierarchy, since the depth of "Root" depends on "Remove Empty Root Objects"
			var rootNode = instance.GetComponentsInChildren<Transform>(true).FirstOrDefault(t => t.name == "Root");
			var rootNodeStart = rootNode ? rootNode.localPosition : Vector3.zero;
			var instanceStart = instance.transform.position;

			graph.SetTimeUpdateMode(DirectorUpdateMode.Manual);
			var output = AnimationPlayableOutput.Create(graph, "Animation", animator);
			output.SetSourcePlayable(AnimationClipPlayable.Create(graph, clip));
			graph.Play();

			const float step = 0.1f;
			for (var t = 0f; t < seconds; t += step)
				graph.Evaluate(step);

			return (instance.transform.position - instanceStart, rootNode ? rootNode.localPosition - rootNodeStart : Vector3.zero, instance.transform.rotation);
		}
		finally
		{
			graph.Destroy();
			Object.DestroyImmediate(instance);
		}
	}

	[TestCase(RootMotionEmptyRoot, true)]
	[TestCase(RootMotionEmptyRoot, false)]
	[TestCase(RootMotionAnimatedRoot, true)]
	[TestCase(RootMotionAnimatedRoot, false)]
	public void Generic_WithRootNode_ClipsHaveMotionCurves(string file, bool removeEmptyRoots)
	{
		var path = Import(file, AnimationMethod.Mecanim, "Root", removeEmptyRoots);
		foreach (var clip in LoadClips(path))
			Assert.IsTrue(clip.hasMotionCurves, $"Clip \"{clip.name}\" animates the root node, so it needs root motion curves");
	}

	[TestCase(RootMotionEmptyRoot)]
	[TestCase(RootMotionAnimatedRoot)]
	public void Generic_WithRootNode_MotionCurvesOnlyContainTheClipsOwnMotion(string file)
	{
		// TurnLeft only rotates the root node. Its motion curves must not pick up the position of another clip
		// that was sampled before it.
		var path = Import(file, AnimationMethod.Mecanim, "Root");
		var turnLeft = LoadClips(path).Single(c => c.name == "TurnLeft");
		foreach (var axis in new[] { "x", "y", "z" })
		{
			var curve = AnimationUtility.GetEditorCurve(turnLeft, EditorCurveBinding.FloatCurve("", typeof(Animator), "MotionT." + axis));
			Assert.IsNotNull(curve, $"MotionT.{axis} is missing");
			Assert.IsTrue(curve.keys.All(k => Mathf.Abs(k.value) < 0.001f), $"TurnLeft doesn't move, but MotionT.{axis} has values up to {curve.keys.Max(k => Mathf.Abs(k.value))}");
		}
	}

	[Test]
	public void Generic_WithoutRootNode_ClipsHaveNoMotionCurves()
	{
		var path = Import(RootMotionEmptyRoot, AnimationMethod.Mecanim);
		foreach (var clip in LoadClips(path))
			Assert.IsFalse(clip.hasMotionCurves, $"Clip \"{clip.name}\" shouldn't get root motion curves without a root node");
	}

	[TestCase(RootMotionEmptyRoot, true)]
	[TestCase(RootMotionEmptyRoot, false)]
	[TestCase(RootMotionAnimatedRoot, true)]
	[TestCase(RootMotionAnimatedRoot, false)]
	public void Generic_WithRootNode_RootMotionMovesInstance(string file, bool removeEmptyRoots)
	{
		var path = Import(file, AnimationMethod.Mecanim, "Root", removeEmptyRoots);
		var (instanceOffset, rootNodeOffset) = PlayClip(path, "WalkForward", 0.9f);

		// WalkForward moves the Root node 1.5m in 1s; with root motion that movement is applied to the instance instead
		var horizontal = Vector3.ProjectOnPlane(instanceOffset, Vector3.up).magnitude;
		Assert.AreEqual(1.35f, horizontal, 0.1f, $"Root motion should move the instance, but it moved {instanceOffset}");
		Assert.Less(Vector3.ProjectOnPlane(rootNodeOffset, Vector3.up).magnitude, 0.01f, "The root node itself should stay in place");
	}

	[Test]
	public void Generic_WithRootNode_RootMotionRotatesInstance()
	{
		var path = Import(RootMotionEmptyRoot, AnimationMethod.Mecanim, "Root");
		var (_, _, rotation) = PlayClipWithRotation(path, "TurnLeft", 0.9f);

		// TurnLeft turns the Root node 90° in 1s (the direction depends on the glTF -> Unity axis conversion)
		Assert.AreEqual(81f, Quaternion.Angle(Quaternion.identity, rotation), 5f, $"Root motion should rotate the instance, but it is at {rotation.eulerAngles}");
	}

	[Test]
	public void Generic_WithoutRootNode_InstanceStaysInPlace()
	{
		var path = Import(RootMotionEmptyRoot, AnimationMethod.Mecanim);
		var (instanceOffset, rootNodeOffset) = PlayClip(path, "WalkForward", 0.9f);

		Assert.Less(instanceOffset.magnitude, 0.01f, $"Without a root node the instance shouldn't move, but it moved {instanceOffset}");
		Assert.Greater(Vector3.ProjectOnPlane(rootNodeOffset, Vector3.up).magnitude, 0.5f, "The Root node itself should be animated");
	}

